const slides = [
  {topic:'The big picture',title:'Three parts work together',body:'<p>The frontend is the interface you use. The backend checks requests and runs application logic. The database stores information the backend needs.</p><p>In this lesson, adding a note connects all three. The response tells the frontend what happened so it can update the page.</p>',example:'<ol class="work-diagram"><li><span class="work-diagram-step">FRONTEND</span><strong>Browser</strong><small>Send a request</small></li><li><span class="work-diagram-step">BACKEND</span><strong>API server</strong><small>Check and process it</small></li><li><span class="work-diagram-step">STORAGE</span><strong>Database</strong><small>Read or save a note</small></li></ol><div class="make-callout">The result returns through the backend to the browser. The browser normally does not connect directly to the database.</div>'},
  {topic:'Read a request',title:'A request describes an action',body:'<dl class="make-terms"><div><dt>Method — what to do</dt><dd>GET retrieves notes. POST submits a new note.</dd></div><div><dt>Path — which resource</dt><dd><code>/api/notes</code> identifies the notes endpoint.</dd></div><div><dt>Body — data to send</dt><dd>A POST body can carry the text of your new note.</dd></div></dl>',example:'<div class="make-code-label">Example request · simplified</div><pre><code>POST /api/notes\nContent-Type: application/json\n\n{ "text": "Learn how APIs work" }</code></pre><div class="make-callout">Read it as: “Create a note with this text.” The backend still needs to validate the request.</div>'},
  {topic:'Read a response',title:'The response explains the outcome',body:'<p>A response includes a status code and may include data. The frontend uses both to decide what to show.</p><p>A successful create request can return the saved note. An invalid request should show a useful error instead of pretending the note was saved.</p>',example:'<table class="make-command-table"><caption>Outcomes you can try here</caption><thead><tr><th>Status</th><th>Meaning in this lesson</th></tr></thead><tbody><tr><td>200 / 201</td><td>Notes loaded / note created.</td></tr><tr><td>401</td><td>Sign-in is required.</td></tr><tr><td>404</td><td>The requested endpoint was not found.</td></tr><tr><td>422</td><td>The note text is invalid.</td></tr><tr><td>503</td><td>The service is unavailable.</td></tr></tbody></table>'},
  {topic:'Trust & validation',title:'The backend checks every request',body:'<p>Frontend validation helps people correct mistakes quickly. Backend validation protects the application even when someone bypasses the interface.</p><ul><li>Check authentication when an action requires sign-in.</li><li>Check whether the user is allowed to perform the action.</li><li>Validate the data before saving it.</li></ul>',example:'<ol class="work-diagram"><li><span class="work-diagram-step">SUBMIT</span><strong>Empty note</strong><small>POST /api/notes</small></li><li><span class="work-diagram-step">VALIDATE</span><strong>Reject it</strong><small>The text is required</small></li><li><span class="work-diagram-step">RESPOND</span><strong>422</strong><small>No new note is saved</small></li></ol><div class="make-callout">Browser code is visible to users. Keep secrets and trusted permission checks on the server.</div>'},
  {topic:'Try the loop',title:'Create, reload, then break a request',body:'<ol><li>Create a note and watch the POST request.</li><li>Reload the list with GET to see the saved note.</li><li>Submit an empty note and compare the error response.</li></ol><p>Use “Start step by step” to pause along the journey. Click the frontend, backend, or database card to read its role.</p>',example:'<div class="make-code-label">Follow the same request in three views</div><ol class="work-diagram"><li><span class="work-diagram-step">APP</span><strong>What you see</strong><small>A note or error message</small></li><li><span class="work-diagram-step">JOURNEY</span><strong>What happens</strong><small>Request → processing → response</small></li><li><span class="work-diagram-step">HTTP</span><strong>What is sent</strong><small>Read the request and response</small></li></ol><p class="make-caption">This is an in-page simulation with example data. Reset notes restores the starting list.</p>'}
];
export function foundationSlidesMarkup() {
  return `<section class="make-deck foundation-deck" aria-labelledby="foundation-deck-title" aria-roledescription="carousel"><header class="make-deck-heading"><div><div class="eyebrow">BEFORE YOU PRACTICE</div><h2 id="foundation-deck-title">Frontend &amp; API essentials</h2></div><span class="foundation-slide-count" aria-live="polite" aria-atomic="true">Slide 1 of ${slides.length}</span></header><nav class="make-slide-topics" aria-label="Foundation slide topics"><div class="make-topic-group"><div>${slides.map((s,i)=>`<button type="button" data-foundation-slide="${i}" aria-pressed="${i===0}" aria-controls="foundation-slide-${i}">${i+1}. ${s.topic}</button>`).join('')}</div></div></nav><div class="make-slide-stage">${slides.map((s,i)=>`<article class="make-slide" id="foundation-slide-${i}" aria-labelledby="foundation-slide-title-${i}" aria-roledescription="slide" ${i?'hidden':''}><div class="make-slide-copy"><h3 id="foundation-slide-title-${i}">${s.title}</h3>${s.body}</div><div class="make-slide-example">${s.example}</div></article>`).join('')}</div><footer class="make-deck-controls"><span>Understand the request, then try it below.</span><div><button type="button" class="secondary" data-foundation-prev disabled>← Previous</button><button type="button" class="secondary" data-foundation-next>Next →</button></div></footer></section>`;
}
export function mountFoundationSlides(root) {
 const buttons=[...root.querySelectorAll('[data-foundation-slide]')],panels=[...root.querySelectorAll('.make-slide')],prev=root.querySelector('[data-foundation-prev]'),next=root.querySelector('[data-foundation-next]');let current=0;
 function show(i){current=Math.max(0,Math.min(slides.length-1,i));buttons.forEach((b,j)=>b.setAttribute('aria-pressed',String(j===current)));panels.forEach((p,j)=>p.hidden=j!==current);prev.disabled=current===0;next.disabled=current===slides.length-1;root.querySelector('.foundation-slide-count').textContent=`Slide ${current+1} of ${slides.length}`;}
 buttons.forEach((b,i)=>b.addEventListener('click',()=>show(i)));prev.addEventListener('click',()=>show(current-1));next.addEventListener('click',()=>show(current+1));root.querySelector('nav').addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();show(e.key==='Home'?0:e.key==='End'?slides.length-1:current+(e.key==='ArrowRight'?1:-1));buttons[current].focus();});
}
